import {Table } from "antd";
import React from 'react';

const Util = {
    round: (num:number, precision: number) => {
        const factor = Math.pow(10, precision);
        return Math.round(num * factor) / factor;
    },
}

export default () => {

    const columns = [
        {
            title: '\u5F00\u652F\u9879',
            dataIndex: 'budget_name',
        },
        {
            title: '\u5355\u4EF7',
            component: 'InputNumber',
            dataIndex: 'budget_unit_price',
        },
        {
            title: '\u6570\u91CF',
            component: 'TextArea',
            customComponentPropsFn: (record: any) => {
                return {
                    maxLength: 10,
                    minLength: 5,
                }
            },
            dataIndex: 'budget_quantity',
        },
        {
            title: '\u8FD9\u9879\u4E0D\u53EF\u4FEE\u6539',
            component: 'Input',
            dataIndex: 'no_update',
            editable: false,
        },
        {
            title: '\u5C0F\u8BA1',
            dataIndex: 'budget_subtotal',
            calc: (record: any) => Util.round((parseFloat(record?.budget_unit_price ?? 0) * parseFloat(record?.budget_quantity ?? 0)), 2)
        },
        {
            title: '\u5907\u6CE8',
            dataIndex: 'budget_remark',
        }
    ];

    const data_resource = [
        {
            key: 1,
            budget_name: '\u529E\u516C\u7528\u54C1',
            budget_unit_price: 2,
            budget_quantity: 3,
            no_update: '\u4E0D\u53EF\u4FEE\u6539\u7684\u503C'
        },
        {
            key: 2,
            budget_name: '\u7ECF\u8D39',
            budget_unit_price: 3,
            budget_quantity: 4,
            no_update: '\u4E0D\u53EF\u4FEE\u6539\u7684\u503C'
        }
    ]

    const summary = (pageData: readonly any[]) => {
        let total = 0;
        pageData.forEach(item => {
            total += Util.round((item?.budget_quantity ?? 0) * (item?.budget_unit_price ?? 0), 2);
        });
        return (
            <>
                <Table.Summary.Row>
                    <Table.Summary.Cell index={0} colSpan={4}>\u5408\u8BA1</Table.Summary.Cell>
                    <Table.Summary.Cell index={1}>
                        <span>{total}</span>
                    </Table.Summary.Cell>
                </Table.Summary.Row>
            </>
        );
    }

    return (
        <Form name="editableEditable" initialValues={{
            data: data_resource
        }}>
            <Form.Item name="data">
                <EditableTable columns={columns} summary={summary} canUpdateNum={'delete_only'} onChange={(value) => {
                    console.log(value);
                }} />
            </Form.Item>
        </Form>
    );
};
